content:
@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    transition: transform 200ms;
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    inline-size: min(24rem, 90vw);
    background-color: var(--shelf-bgColor-raised);
    transition: transform var(--shelf-motion-duration-fast);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    animation-name: fade-in;
    animation-duration: 300ms;
  }
}

@layer components {
  .chip {
    display: inline-flex;
    align-items: center;
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    border-radius: var(--shelf-radius-full);
    transition-timing-function: ease-in-out;
  }
}

@layer components {
  .chip {
    display: inline-flex;
    align-items: center;
    padding: var(--shelf-space-xs) var(--shelf-space-sm);
    border-radius: var(--shelf-radius-full);
    transition-timing-function: var(--shelf-motion-easing-enter);
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
    transition: transform 0.3s ease;
  }
}

@layer tokens {
  :root {
    --shelf-motion-duration-fast: 150ms;
    --shelf-motion-duration-base: 300ms;
    --shelf-motion-duration-slow: 500ms;
    --shelf-motion-easing-enter: cubic-bezier(0.0, 0.0, 0.2, 1);
    --shelf-motion-easing-exit: cubic-bezier(0.4, 0.0, 1, 1);
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    transition-timing-function: linear;
  }
}
